import re


def get_id_from_dist_name(dist_name):
    """
    Get ID from distName
    :param dist_name:   distName
    return:             ID
    """
    ru_pattern = re.search(r"(?P<ID>\d+)$", dist_name)
    ru_id = ru_pattern.group("ID")
    return ru_id


def get_substring_from_dist_name(dist_name, start=0, end=-1):
    """
    Get substring from distName. By default, it returns substring from start to the last object
    :param dist_name:   distName
    :param start:       start index
    :param end:         end index
    """
    return "/".join(dist_name.split("/")[start:end])


def get_device_name_based_on_dist_name(dist_name):
    """
    Get device name based on distName (last object in distName path)
    :param dist_name:   distName
    return:             device name
    """
    return get_substring_from_dist_name(dist_name, start=-1, end=None)


def get_cell_runtime_based_on_dist_name(bts_info, cell_dn):
    """
    Get cell runtime based on distName
    :param bts_info:    BTS info
    :param cell_dn:     cell distName
    return:             cell runtime dist name
    """
    for cell_type in bts_info["cells"]:
        for cell_info in bts_info["cells"][cell_type]:
            if cell_info["id"]["configuration"] == cell_dn:
                return cell_info["id"]["internal"]
